import SwiftUI

struct OnboardingWizard: View {
    var resume_token: String? = nil
    var total_steps: Int = 3

    var onStepChanged: (((from: Int, to: Int)) -> Void)? = nil
    var onCompleted: (([String: Any]) -> Void)? = nil
    var onAbandoned: ((Int) -> Void)? = nil

    @State private var currentStep: Int = 1
    @State private var name: String = ""
    @State private var email: String = ""

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("Onboarding-Wizard")
                .font(.title)
            Text("Schritt \(currentStep) von \(total_steps)")
                .font(.subheadline)
            if let token = resume_token {
                Text("Resume-Token: \(token)")
                    .font(.caption)
            }

            Divider()

            Group {
                if currentStep == 1 {
                    Text("Begrüßung")
                        .font(.headline)
                    Text("Willkommen! Lass uns dein Profil einrichten.")
                } else if currentStep == 2 {
                    Text("Profil-Daten")
                        .font(.headline)
                    TextField("Name", text: $name)
                        .textFieldStyle(.roundedBorder)
                    TextField("E-Mail", text: $email)
                        .textFieldStyle(.roundedBorder)
                } else if currentStep == total_steps {
                    Text("Bestätigung")
                        .font(.headline)
                    Text("Name: \(name)")
                    Text("E-Mail: \(email)")
                } else {
                    Text("Schritt \(currentStep)")
                        .font(.headline)
                }
            }

            Spacer()

            HStack {
                Button("Zurück") {
                    let from = currentStep
                    let to = max(1, currentStep - 1)
                    if from != to {
                        currentStep = to
                        onStepChanged?((from: from, to: to))
                    }
                }
                .disabled(currentStep <= 1)

                Spacer()

                if currentStep < total_steps {
                    Button("Weiter") {
                        let from = currentStep
                        let to = min(total_steps, currentStep + 1)
                        if from != to {
                            currentStep = to
                            onStepChanged?((from: from, to: to))
                        }
                    }
                } else {
                    Button("Fertig") {
                        onCompleted?(["name": name, "email": email])
                    }
                }
            }
        }
        .padding()
        .onDisappear {
            if currentStep < total_steps {
                onAbandoned?(currentStep)
            }
        }
    }
}
